import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd(); fz = repo / 'target/debug/fz'

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run([str(fz), 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return root, payload

def messages(payload):
    return [item['message'] for item in payload['items']]

_, leak = verify('file_leak', '''
    use core.fs;
    fn main() -> i32 {
        let file = fs.open("/tmp/fzy-file-leak-scenario.txt")
        discard fs.write(file, "hello")
        return 0
    }
''', 1)
assert any('linear value `file` was not consumed/freed' in message for message in messages(leak)), leak

_, reuse = verify('file_reuse', '''
    use core.fs;
    fn close_file(file: FileHandle) -> i32 {
        return fs.close(file)
    }
    fn main() -> i32 {
        let file = fs.open("/tmp/fzy-file-reuse-scenario.txt")
        discard fs.write(file, "hello")
        discard close_file(file)
        discard fs.close(file)
        return 0
    }
''', 1)
assert any('uses moved value `file` after move/consume' in message for message in messages(reuse)), reuse

return_root, returned = verify('file_return', '''
    use core.fs;
    fn open_file() -> FileHandle {
        return fs.open("/tmp/fzy-file-return-scenario.txt")
    }
    fn main() -> i32 {
        let file = open_file()
        discard fs.write(file, "hello")
        discard fs.close(file)
        return 0
    }
''', 0)
assert returned['errors'] == 0, returned
assert not any('resource escape' in message for message in messages(returned)), returned
handle_contracts = json.loads((return_root / '.fz' / 'handle-contracts.json').read_text())
runtime_contracts = json.loads((return_root / '.fz' / 'native-runtime-contracts.json').read_text())
handle_text = json.dumps(handle_contracts)
runtime_text = json.dumps(runtime_contracts)
assert 'FileHandle' in handle_text, handle_contracts
assert 'fs.open' in runtime_text and 'owned_file_handle' in runtime_text, runtime_contracts
assert 'fs.close' in runtime_text and 'consume_arg0' in runtime_text, runtime_contracts

runtime_path = pathlib.Path(tempfile.mkdtemp(prefix='fozzylang-file-runtime-')) / 'roundtrip.txt'
runtime_root = write_project('file_runtime', f'''
    use core.fs;
    fn main() -> i32 {{
        let file = fs.open("{runtime_path.as_posix()}")
        discard fs.write(file, "hello")
        discard fs.flush(file)
        discard fs.fsync(file)
        let body = fs.read(file, 32)
        discard fs.close(file)
        if body == "hello" {{
            return 0
        }}
        return 1
    }}
''')
run_proc = subprocess.run([str(fz), 'run', str(runtime_root), '--proc-backend', 'host', '--fs-backend', 'host', '--http-backend', 'host', '--json'], cwd=str(repo), capture_output=True, text=True)
run_payload = json.loads(run_proc.stdout.strip())
assert run_proc.returncode == 0, (run_proc.returncode, run_payload, run_proc.stderr)
assert run_payload['status'] == 'pass', run_payload
assert runtime_path.read_text() == 'hello', runtime_path.read_text()

print('compiler-memory-file-handles-ok')

